/**
 * @file
 *
 * @brief Public kernel APIs.
 */

#ifndef ZEPHYR_INCLUDE_KERNEL_H_
#define ZEPHYR_INCLUDE_KERNEL_H_

#if !defined(_ASMLANGUAGE)
#include <zephyr/kernel_includes.h>
#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <zephyr/toolchain.h>
#include <zephyr/tracing/tracing_macros.h>
#include <zephyr/sys/mem_stats.h>
#include <zephyr/sys/iterable_sections.h>

#ifdef __cplusplus
extern "C" {
#endif

/*
 * Zephyr currently has a huge circular dependency ground-zero between
 * kernel.h and arch/cpu.h (and everything they include). Until this is
 * resolved, keep the remaining contents of kernel.h in a separate file
 * or include it carefully.
 */

/**
 * @brief Kernel APIs
 * @defgroup kernel_apis Kernel APIs
 * @ingroup os_services
 * @{
 * @}
 */

#define K_ANY (NULL)
#define K_END (NULL)

#ifdef CONFIG_KERNEL_COHERENCE
#define K_MEM_COHERENT __attribute__((section(".cached_bss")))
#else
#define K_MEM_COHERENT
#endif

#endif /* !_ASMLANGUAGE */

/*Stubs cannot reconstruct the 6000-line kernel.h without tests/kernel/timer/timer_api/src/main.c*/
#endif
